   $redirectParts=parse_url($a['redirect_uri']);$redirectOrigin=$redirectParts['scheme'].'://'.$redirectParts['host'].(isset($redirectParts['port'])?':'.$redirectParts['port']:'');header('Content-Type: text/html; charset=utf-8');header('Referrer-Policy: same-origin');header("Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'unsafe-inline'; form-action 'self' ".$redirectOrigin."; frame-ancestors 'none'; base-uri 'none'");$scopeHtml=htmlspecialchars($a['scope'],ENT_QUOTES,'UTF-8');echo '<!doctype html><html lang="en"><meta name="referrer" content="same-origin"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Connect Khosra</title><style>body{font-family:system-ui;background:#f4f5ed;color:#344c3c;max-width:440px;margin:12vh auto;padding:28px}h1{font-family:Georgia;font-weight:400;font-size:36px}p{line-height:1.8}input,button{box-sizing:border-box;display:block;width:100%;padding:14px;margin:15px 0;border:1px solid #cbd8bf;border-radius:7px;font:inherit}button{background:#246b5b;color:white}small{color:#64765a}.password-field{position:relative;margin:15px 0}.password-field input{margin:0;padding-right:94px}.password-field .password-reveal{position:absolute;top:1px;right:1px;width:80px;min-height:48px;margin:0;padding:8px;border:0;background:transparent;color:#305f50;font-size:14px}[hidden]{display:none!important}</style><script src="/oauth-consent.js" defer></script><h1>Connect your writing room.</h1><p>Allow this connection to read your private manuscript and, when permitted, save proposals and context indexes. It cannot accept revisions.</p><p>Permissions: '.$scopeHtml.'</p><form method="post" action="/api/oauth/authorize"><input type="hidden" name="nonce" value="'.$nonce.'"><label for="consent-password">Owner password</label><div class="password-field"><input id="consent-password" type="password" name="password" autocomplete="current-password" required><button id="reveal-password" class="password-reveal" type="button" aria-controls="consent-password" aria-label="Show password" aria-pressed="false" hidden>Show</button></div><button name="decision" value="allow">Allow connection</button><button name="decision" value="deny" formnovalidate>Cancel</button></form><small>Your manuscript is shared with ChatGPT only when its tools retrieve it. No model API billing is involved.</small></html>';exit;
  }
  if($method!=='POST')fail(405,'GET or POST required.');$pending=$_SESSION['consent']??null;unset($_SESSION['consent']);if(!$pending||$pending['expires']<time()||!hash_equals($pending['nonce'],(string)($body['nonce']??'')))fail(403,'Consent expired. Restart connection.');$a=$pending['args'];$location=$a['redirect_uri'].(str_contains($a['redirect_uri'],'?')?'&':'?').http_build_query(['state'=>$a['state'],'iss'=>rtrim($config['origin'],'/')]);if(($body['decision']??'')!=='allow'){header('Location: '.$location.'&error=access_denied',true,303);exit;}throttle($db,'consent',8);if(!text($body['password']??null,1000)||!ownerPasswordMatches($body['password'],$config))fail(401,'Incorrect owner password. Restart connection.');$code=bin2hex(random_bytes(32));$q=$db->prepare('INSERT INTO oauth_codes(code_hash,client_id,redirect_uri,resource,scope,challenge,expires_at) VALUES(?,?,?,?,?,?,?)');$q->execute([hash('sha256',$code),$a['client_id'],$a['redirect_uri'],$a['resource'],$a['scope'],$a['code_challenge'],time()+120]);session_regenerate_id(true);header('Location: '.$location.'&code='.urlencode($code),true,303);exit;
 }
 if($path==='oauth/token'&&$method==='POST'){
  throttle($db,'token',120);if(($body['resource']??'')!==oauthResource($config))fail(400,'Invalid resource audience.');beginWrite($db);try{
   if(($body['grant_type']??'')==='authorization_code'){$q=$db->prepare('SELECT * FROM oauth_codes WHERE code_hash=?'.databaseLock($db));$q->execute([hash('sha256',(string)($body['code']??''))]);$row=$q->fetch(PDO::FETCH_ASSOC);$verifier=(string)($body['code_verifier']??'');if(!preg_match('/^[A-Za-z0-9._~-]{43,128}$/',$verifier)||!$row||(int)$row['expires_at']<=time()||$row['client_id']!==($body['client_id']??'')||$row['redirect_uri']!==($body['redirect_uri']??'')||$row['resource']!==$body['resource']||!hash_equals($row['challenge'],rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'=')))fail(400,'Invalid authorization grant or PKCE verifier.');$q=$db->prepare('DELETE FROM oauth_codes WHERE code_hash=?');$q->execute([$row['code_hash']]);
   }elseif(($body['grant_type']??'')==='refresh_token'){$q=$db->prepare('SELECT * FROM oauth_tokens WHERE refresh_hash=?'.databaseLock($db));$q->execute([hash('sha256',(string)($body['refresh_token']??''))]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row||(int)$row['revoked']!==0||(int)$row['refresh_expires_at']<=time()||$row['client_id']!==($body['client_id']??'')||$row['resource']!==$body['resource'])fail(400,'Invalid refresh token.');$q=$db->prepare('UPDATE oauth_tokens SET revoked=1 WHERE access_hash=?');$q->execute([$row['access_hash']]);
   }else fail(400,'Unsupported grant type.');$result=issueTokens($db,$row['client_id'],$row['resource'],$row['scope']);$db->commit();respond($result);
