 }
 if($path==='oauth/revoke'&&$method==='POST'){throttle($db,'revoke',120);$hash=hash('sha256',(string)($body['token']??''));$q=$db->prepare('UPDATE oauth_tokens SET revoked=1 WHERE (access_hash=? OR refresh_hash=?) AND client_id=?');$q->execute([$hash,$hash,(string)($body['client_id']??'')]);respond(['revoked'=>true]);}
